      $('#nozomi-anchor-date').text(_.get(all_variables, 'stat_data.文本5.文本7.文本2', 'N/A'));
      $('#nozomi-anchor-time').text(_.get(all_variables, 'stat_data.文本5.文本7.文本4', 'N/A'));
      $('#nozomi-outfit').text(_.get(all_variables, 'stat_data.文本5.文本8', 'N/A'));
    }

    function populateBodyData() {
      const all_variables = getAllVariables();
      $('#body-head').text(_.get(all_variables, 'stat_data.文本5.文本9.文本10', 'N/A'));
      $('#body-torso').text(_.get(all_variables, 'stat_data.文本5.文本9.文本11', 'N/A'));
      $('#body-limbs').text(_.get(all_variables, 'stat_data.文本5.文本9.文本12', 'N/A'));
      $('#body-genitals').text(_.get(all_variables, 'stat_data.文本5.文本9.文本13', 'N/A'));
    }

    function populateMentalData() {
      const all_variables = getAllVariables();
      $('#phantom-pain').text(_.get(all_variables, 'stat_data.文本5.文本14', 'N/A'));
      $('#inner-thought').text(_.get(all_variables, 'stat_data.文本5.文本15', 'N/A'));
    }

    function populateDeathLibrary() {
      const all_variables = getAllVariables();
      const death_lib = _.get(all_variables, 'stat_data.文本5.文本16', {});
      const $tbody = $('#death-table-body');
      $tbody.empty();

      const sorted_deaths = Object.entries(death_lib).sort((a, b) => b[1].文本18 - a[1].文本18);

      if (sorted_deaths.length === 0) {
        $tbody.append($('<tr>').append($('<td colspan="4">').css('text-align', 'center').css('color', '#999').text('文本17')));
        return;
      }

      sorted_deaths.forEach(([name, data]) => {
        const $row = $('<tr>');
        $row.append($('<td>').text(name));
        $row.append($('<td>').addClass('death-count').text(data.文本18));
        $row.append($('<td>').text(data.文本19 || 'N/A'));
        $row.append($('<td>').text(data.文本20 || '-'));
        $tbody.append($row);
      });
    }

    function setupTabs() {
      $('.tab-button').on('click', function() {
        const tab_id = $(this).data('tab');
        $('.tab-button').removeClass('active');
        $(this).addClass('active');
        $('.tab-content').removeClass('active');
        $(`#${tab_id}`).addClass('active');
      });
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateWorldData();
      populateBasicData();
      populateBodyData();
      populateMentalData();
      populateDeathLibrary();
      setupTabs();
    }

    $(errorCatched(init));
  </script>
</head>

